param(\n    [Parameter(Mandatory=$true)][string]$DumpRoot,\n    [string]$OutputRoot = ""\n)\n\n$ErrorActionPreference = "Stop"\n$Here = Split-Path -Parent $MyInvocation.MyCommand.Path\n\nif ([string]::IsNullOrWhiteSpace($OutputRoot)) {\n    $OutputRoot = Join-Path $Here "output\\postdecrypt"\n}\n\nNew-Item -ItemType Directory -Force -Path $OutputRoot | Out-Null\n\n$Report = Join-Path $OutputRoot "postdecrypt-report.json"\n$Stage = Join-Path $OutputRoot "anyps5-input"\n\npython (Join-Path $Here "postdecrypt_intake.py") $DumpRoot -o $Report --stage $Stage\n$ExitCode = $LASTEXITCODE\n\nWrite-Host ""\nWrite-Host "Report : $Report"\nWrite-Host "Stage  : $Stage"\nexit $ExitCode\n